from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();p=R/'analysis/v192_normalized_hollow_wing_study.json';d=json.loads(p.read_text());assert d['status']=='NORMALIZED_HOLLOW_WING_STUDY_SAVED_REOPENED_BALANCE_MEASURED';assert len(d['rows'])==3 and [r['object'] for r in d['rows']]==['SOURCE_WING','NORMALIZED_CAVITY','HOLLOW_WING_CANDIDATE'];assert all(r['valid'] and r['solids']==1 for r in d['rows']);assert d['rows'][2]['shells']==2
for n,h in d['input_sha256_unchanged'].items():assert H(R/'migration/freecad'/n)==h
cad=R/'migration/freecad/WING_R_NORMALIZED_CAVITY_HOLLOW_STUDY_ONLY.FCStd';assert H(cad)==d['output_sha256'];assert abs(d['fused_saved_reopen_default_volume_delta_mm3'])<1e-8;assert abs(d['reopened_hollow_default_volume_mm3']-d['rows'][2]['default_volume_mm3'])<1e-8
assert d['fused_native_exact_method_valid'] and abs(d['fused_outside_current_wing_volume_mm3'])<1e-7 and d['fused_min_distance_to_current_wing_boundary_mm']>0
for key,method in [('default_wing_minus_cavity_minus_hollow_mm3','default_volume_mm3'),('GK_wing_minus_cavity_minus_hollow_mm3','GK_volume_mm3')]:assert d['rows'][0][method]-d['rows'][1][method]-d['rows'][2][method]==d[key]
out=R/'analysis/v192_normalized_hollow_wing_verification.json';assert not out.exists();out.write_text(json.dumps({'status':'NORMALIZED_HOLLOW_WING_REPORT_SCOPE_HASHES_AND_BALANCES_VERIFIED','input_report_sha256':H(p),'candidate_sha256':H(cad),'default_balance_residual_mm3':d['default_wing_minus_cavity_minus_hollow_mm3'],'adaptive_GK_balance_residual_mm3':d['GK_wing_minus_cavity_minus_hollow_mm3'],'default_numeric_balance_within1e_minus5':abs(d['default_wing_minus_cavity_minus_hollow_mm3'])<1e-5,'adaptive_GK_numeric_balance_within1e_minus5':abs(d['GK_wing_minus_cavity_minus_hollow_mm3'])<1e-5,'default_minus_GK_volumes_by_object_mm3':{r['object']:r['default_volume_mm3']-r['GK_volume_mm3'] for r in d['rows']},'min_current_wing_boundary_gap_mm':d['fused_min_distance_to_current_wing_boundary_mm'],'limits':['Conservation of numerical volume does not certify absolute volume accuracy','Current wing OML remains heuristic and unregistered to complete primary aircraft geometry','No saved partition, updated seam/structure, manufacturing or flight acceptance'],'print_release':False,'flight_release':False},indent=2)+'\n');print('Hollow candidate report verified',d['default_wing_minus_cavity_minus_hollow_mm3'],d['GK_wing_minus_cavity_minus_hollow_mm3'])
